/** Each published script's story and spoken lines as plain text, by film slug (a film's language versions' scripts after its own): what the search matches a script on. */
export const MOTION_SCRIPT_WORDS: Readonly<Record<string, string>> = {
  'blog-designing-docs': 'Most docs readers are now AI agents, which makes an intuitive, intentional docs interface even more important, so General Translation redesigned its docs from scratch around its writing: it deleted the clutter, made the sidebar one accordion, gave the writing open space, kept translated pages aligned and pointed each page at what its reader wants, and it still treats docs design as an open problem. Most docs readers are now AI agents. An intuitive, intentional docs interface becomes even more important. General Translation redesigned its docs from scratch so people would read its writing. Interfaces keep getting more cluttered, which creates mental clutter. The redesign started by deleting extra lines, links, and buttons. The sidebar is now one accordion, which is rare among docs sites. The writing now has more open space around it. Translated pages keep the same spacing and alignment. Each page guides its reader toward the action they want. Docs design is an open problem, and the team keeps working on it.',
  'blog-rewriting-docs': 'Docs now have two readers, so General Translation rebuilt its docs for both: for people each page starts with what it covers, and for agents every page is also served as raw Markdown. Docs now have two readers: people and AI agents. General Translation rebuilt its docs from scratch for both. For people, each page starts with what it covers and when to use it. For agents, every page is also served as raw Markdown.',
  'blog-fuma-nama': 'One developer, Fuma Nama, created Fumadocs, a docs framework with over 13,000 GitHub stars that Vercel Turborepo, shadcn/ui, Better Auth, Unkey and many others use, and he has built it for three years on top of his schoolwork. He learned to code by modding games and reading code, and he did not read documentation. He designed Fumadocs in four layers that developers can take apart, down to copying only the table of contents into their own code. He thinks he would build it the same shape again, and General Translation has made it its first open-source grantee. One developer created Fumadocs, a docs framework with over 13,000 stars on GitHub. Vercel Turborepo, shadcn/ui, Better Auth, Unkey and many others use it. Fuma Nama has built it for three years, on top of his schoolwork. He learned to code by modding games and reading piles of JavaScript. He did not look at any documentation while he was learning. He designed Fumadocs in four layers that developers can take apart and reshape. The CLI can copy just the table of contents into your codebase. If he started again from scratch, he thinks Fumadocs would probably have the same shape. Fumadocs is General Translation’s first open-source grantee.',
  'release-board': 'A split-flap board fills with the newest releases of General Translation\'s packages, and the newest, gt 2.23, lets you sign in and set up projects from the CLI. This board lists the newest releases of General Translation’s packages. The newest, gt 2.23, lets you sign in and set up projects from the CLI.',
  'slash-announcement': 'Slash is building the financial command center for businesses and supports sending and receiving global payments to 180+ countries. General Translation is partnering with Slash, and eligible Slash customers can receive up to $2,000 in translation credits for their app, website, documentation, slides and design files. Slash is building the financial command center for businesses. They support sending and receiving global payments to over 180 countries. We\'re excited to partner with Slash to help ambitious companies reach customers in every language. So if you bank with Slash, we\'re giving you up to two thousand dollars in translation credits to localize any product surface. That covers your app, website, documentation, slides, design files, and more. Your product should exist in every language. The German version of General Translation\'s Slash announcement: Slash is building the financial command center for businesses and supports global payments to more than 180 countries; General Translation is partnering with Slash, and eligible Slash customers can receive up to $2,000 in translation credits for their app, website, documentation, slides and design files. Draft translation, for a native speaker\'s check. Slash entwickelt die Kommandozentrale für Unternehmensfinanzen. Damit senden und empfangen Unternehmen internationale Zahlungen in mehr als 180 Ländern. Wir freuen uns, als Partner von Slash ambitionierten Unternehmen zu helfen, Kunden in jeder Sprache zu erreichen. Wenn Ihr Unternehmen also Slash nutzt, erhalten Sie von uns bis zu 2.000 Dollar Übersetzungsguthaben, um jeden Teil Ihres Produkts zu lokalisieren. Das umfasst Ihre App, Website, Dokumentation, Folien, Designdateien und mehr. Ihr Produkt sollte in jeder Sprache existieren. The Spanish version of General Translation\'s Slash announcement: Slash is building the financial command center for businesses and supports global payments to more than 180 countries; General Translation is partnering with Slash, and eligible Slash customers can receive up to $2,000 in translation credits for their app, website, documentation, slides and design files. Draft translation, for a native speaker\'s check. Slash está construyendo el centro de control financiero para empresas. Permite enviar y recibir pagos internacionales en más de 180 países. Nos entusiasma asociarnos con Slash para ayudar a empresas ambiciosas a llegar a clientes en todos los idiomas. Si usas Slash, te damos hasta 2000 dólares en créditos de traducción para localizar cualquier parte de tu producto. Eso incluye tu app, sitio web, documentación, diapositivas, archivos de diseño y más. Tu producto debería existir en todos los idiomas. The Japanese version of General Translation\'s Slash announcement: Slash is building the financial command center for businesses and supports global payments to more than 180 countries; General Translation is partnering with Slash, and eligible Slash customers can receive up to $2,000 in translation credits for their app, website, documentation, slides and design files. Draft translation, for a native speaker\'s check. Slashは、企業財務の司令塔をつくっています。送金と受け取りの対応国は、180か国以上です。 Slashと提携し、意欲的な企業があらゆる言語で顧客とつながるお手伝いができて、うれしく思います。 Slashをご利用の方には、最大で2,000ドル分の翻訳クレジットを提供し、プロダクトのどの部分のローカライズにも使えます。 対象は、アプリ、ウェブサイト、ドキュメント、スライド、デザインファイルなどです。 あなたのプロダクトは、あらゆる言語で存在すべきです。',
  'jihe-yuanben': 'The Chinese word for geometry, 幾何, is often said to copy the sound of “geo.” In the 1607 Chinese Euclid it was the ordinary word for “how much.” Only six books of plane geometry existed in Chinese for 250 years, so the word for “how much” came to mean geometry. This title begins with the Chinese word for geometry. It is often said to copy the sound of geo. In 1606 two men in Beijing began to translate Euclid’s geometry. Only one of them could read Latin. 泰西，利瑪竇，口譯。 Matteo Ricci translated by mouth. 吳淞，徐光啓，筆受。 Xu Guangqi wrote it down with the brush. Chinese mathematics was written as questions, such as how large a field 15 paces by 16 is. That question ends with the title’s first two characters. A commentary written in 263 CE justified those methods by cutting figures apart and reassembling them. Euclid never asks a question, and he defines every object first. Chinese had no word for definition, so Ricci and Xu made one meaning “an account of boundaries.” A, B and C were only sounds, so they used a series every literate reader could recite. 甲、乙、丙、丁。 These are the first four Heavenly Stems. Those two characters were the ordinary word for “how much.” Ricci and Xu used them to mean quantity. For 250 years Chinese readers had only six of Euclid’s books, all on plane geometry. So the word for “how much” came to mean geometry.',
  'journey-to-the-west': 'The monkey hero’s surname is the word for macaque with its animal part taken off. The novel hides more monkeys in his stable title and calls him the mind-monkey. Arthur Waley’s 1942 English called him Monkey, and in 2021 that is still his English name. In the Chinese novel Journey to the West, the monkey hero’s surname comes from the word for macaque, with the animal part removed. Without the animal part, the second character leaves boy and infant, so his surname is Sun. In 1942 Arthur Waley’s English translation left this out, and a footnote translated Sun as Monkey. Waley called the book Monkey too. He kept thirty of the hundred chapters. In the novel, Heaven gives the monkey a post in the imperial stables. 弼馬溫 bìmǎwēn 避馬瘟 bìmǎwēn The title is usually heard as ward off horse plague. Chinese stables kept a macaque for that job. In the oldest surviving edition, the chapter titles call him the mind-monkey. The scholar Hu Shih introduced Waley’s book to Americans as humour and satire, freed from allegorical readings. Waley’s Monkey travels west with Pigsy the pig, Sandy the river monster and Tripitaka the monk. In 2021 Julia Lovell’s translation kept all four names, and its hero is still Monkey.',
  'modern-hebrew': 'For about seventeen centuries Hebrew was no one’s mother tongue. Eliezer Ben-Yehuda built new words from its own roots and marked his accepted coinages in his dictionary with a small sign. The tomato word he refused to print is the word Hebrew speakers use today. For about seventeen centuries, Hebrew was no one’s mother tongue. Jews read and wrote it, but many modern things had only phrases for names. Even a dictionary was called sefer milim, a copy of German Wörterbuch. In 1880 Eliezer Ben-Yehuda wrote that such copies had made Hebrew almost German. Instead he made milon from mila, which means word. The letter mem can mark a tool, so he put it before the root for sling and made makle’a, a cannon. In his own dictionary, this sign marks words he coined that people had already accepted. It stands before the bicycle, a word for two wheels modeled on the word for ears. No one is sure what the prophet Ezekiel meant by khashmal. An ancient Greek translation gave it as elektron, so a poet used it for electricity. Ben-Yehuda did not mark that word as his own. Yehiel Michel Pines apparently named the tomato agvaniya, from a root that means desire. Ben-Yehuda found the word immodest and kept it out of his dictionary. Today Hebrew speakers call the tomato by the word he kept out.',
  'nishi-amane': 'Japanese and Chinese both write “philosophy” 哲學. Nishi Amane took 希 from Zhou Dunyi’s line that the scholar aspires to be worthy and named the study kitetsugaku in 1861, dropped the 希 by 1870, chose tetsugaku over rigaku to keep it apart from Confucian learning, and printed it in 1874 in a sentence that runs over a page turn. His lectures also gave Japanese its words for induction, deduction, definition and proposition; Chinese books took up the word from 1889, Wang Guowei argued in 1905 for keeping the Japanese terms, and two of those words replaced the ones Ricci and Xu had made for Euclid. Japanese and Chinese write philosophy with these two characters. A translator named Nishi Amane made the word. Nishi trained as a Confucian scholar before he learned Dutch and English. The eleventh-century Chinese philosopher Zhou Dunyi had written that the scholar aspires to be worthy. In 1861 Nishi used that line to name philosophy kitetsugaku, the study that aspires to wisdom. By 1870 he had dropped the first character, and the word was tetsugaku. The direct translation would have been rigaku. Nishi wrote that he chose tetsugaku to set philosophy apart from Confucian learning. The word reached print in a book of 1874. The sentence that names it runs over a page turn. ヒロソヒー、譯シテ哲學ト名ケ “philosophy, which I translate and name tetsugaku” His lectures of 1870 and 1871 had also given Japanese words to induction, deduction, definition and proposition. In 1889 a Chinese book about Japan explained the word as the Western study of human nature. In 1905 the scholar Wang Guowei wrote that Japanese scholars had fixed such terms first, so Chinese could use them. Two words first recorded in Nishi’s lectures replaced the words Matteo Ricci and Xu Guangqi chose for Euclid in 1607. Chinese now uses them for definition and proposition.',
  'tyndale': 'William Tyndale translated scripture into English while church law forbade it. His New Testament, translated from the Greek, was printed at Worms in 1526 and burned in London; his Pentateuch of 1530, printed under a false imprint, is where the Oxford English Dictionary first records passover, scapegoat and mercy seat. Thomas More attacked his choice of congregation for church, the King James translators kept church, and a 1998 sampling study estimated how much of his wording the King James Version kept. He was arrested in 1535 and executed at Vilvoorde in 1536. William Tyndale translated scripture into English while church law forbade it, and English still uses words first recorded in his translations. He translated the New Testament from the Greek, and it was printed at Worms in 1526. Copies reached England, and the Bishop of London had them collected and burned at St Paul\'s Cross. In exile he learned Hebrew, and in 1530 he published the five books of Moses under a false imprint. playnly layde before their eyes in their mother tonge Where the Latin Bible had phase and explained it as the passing of the Lord, Tyndale wrote passover. The goat sent into the wilderness became the scapegoat, and Luther\'s German Gnadenstuhl became the mercy seat. The Oxford English Dictionary first records all three words in this book. His New Testament has phrases still in use, such as the signs of the times and the powers that be. Thomas More attacked his choice of congregation for church, and in 1611 the King James translators kept church. A 1998 sampling study estimates that Tyndale\'s contribution to the King James New Testament is about 84 percent of the text. In the Old Testament, about 76 percent of his words were retained. He was arrested in Antwerp in 1535. In prison he asked for his Hebrew Bible, grammar and dictionary. In 1536 he was strangled and burned at Vilvoorde.',
  'hunayn': 'The word retina is already in a Latin version of Ḥunayn ibn Isḥāq’s Arabic book on the eye; his letter on the Galen translations lists 129 works and records how he collated several Greek copies into one correct text before he corrected his translation; his nephew Ḥubaysh put many of his Syriac versions into Arabic, and a later historian says some readers scraped Ḥubaysh’s name off them and wrote Ḥunayn’s; his book gives each coat of the eye a Greek name and an Arabic name that translates it, and Constantine the African’s Latin called three of them retina, uvea and cornea; and the House of Wisdom that popular histories put him in charge of is not in his letter. The word retina is already in a Latin version of an Arabic book on the eye. The Arabic book is by Ḥunayn ibn Isḥāq, who translated the works of the Greek physician Galen in ninth-century Baghdad. His letter lists 129 works and says which ones had been translated, and by whom. He translated one of them at about twenty, from a single Greek copy with many gaps. At about forty he compared several copies until one correct text emerged, and corrected his translation against it. وكذلك من عادتي أن أفعل في جميع ما أترجمه “This is my habit in everything I translate.” He searched Syria, Palestine and Egypt for Galen\'s On Demonstration and found about half of it in Damascus. His son Isḥāq translated Greek philosophy, and his nephew Ḥubaysh put many of Ḥunayn\'s Syriac versions into Arabic. A later historian says some readers scraped Ḥubaysh\'s name off his translations and wrote Ḥunayn\'s. His book on the eye gives each coat its Greek name and an Arabic name that translates it. Constantine the African translated it into Latin under his own name and called these coats retina, uvea and cornea. Popular histories put Ḥunayn in charge of an academy called the House of Wisdom. His letter never mentions it and names the people he translated for. The historian Dimitri Gutas argues that it was a library in the caliphs\' administration.',
  'kb-best-localization-software': 'Look for one system that covers the whole pipeline, from the i18n library in your code to translation and delivery. In Mexico City, a reader of Spanish gets your Home page in English. Its English is in the component, and nothing in the project translates it. General Translation covers the whole pipeline, from your code to translation and delivery. Run npx gt init and wrap the content in a T component, with no keys to write. One command in your build writes the German, Japanese and Spanish translations. Once your repository is connected, Locadex can open a pull request with new translations when you push. In Mexico City, the Home page now opens in Spanish.',
  'kb-what-is-locadex': 'Locadex is General Translation\'s AI agent. Connected to a GitHub repository, it opens pull requests that set up internationalization, wrap untranslated text in the right i18n calls, translate new content into every target language, and keep locale files in sync. In Nagoya, your app offers Spanish and French, and a Japanese reader gets English. The app\'s gt.config.json lists Spanish and French, and nothing else. General Translation uses its AI agent Locadex to open pull requests that translate your app. Connect GitHub in the Dashboard, and create an automation from a template. Run setup with Japanese as a target, and Locadex opens a pull request. Turn on auto-merge, and Locadex merges its pull requests when checks pass. After the merge, the automation translates into every target language. Along with Spanish and French, your app now opens in Japanese in Nagoya.',
  'kb-i18n-without-translation-files': 'Yes. With gt-react or gt-next, content stays inline in your components inside a <T> component, and translations are generated at build time as output, so there are no keys or per-locale JSON files to write and keep in sync. In Tokyo, your checkout page opens in Japanese with one line still in English. Its key went into en.json, and nobody added it to ja.json. General Translation lets you stop writing translation files with gt-react or gt-next. Run npx gt init to set up gt-next and choose your languages. Write the English inside a T component, and nobody has to update ja.json by hand. Then add npx gt translate to your build script, and every build writes the Japanese. Now the tax line appears in Spanish, French and Japanese with the rest of the page.',
  'kb-add-i18n-to-nextjs': 'Install gt-next and the gt CLI, wrap your Next.js config with withGTConfig, list your languages in gt.config.json, add a loadTranslations file and the GTProvider, wrap your content in the T component, and run npx gt translate before next build. In Osaka, your page is in English, with no way to choose Japanese. Its text is plain JSX, and the app has no i18n library. General Translation lets you add i18n with gt-next: wrap text in T and generate translations. Wrap your config in withGTConfig, list your languages, and add a file that loads their translations. Put the GTProvider in your root layout, wrap text in T, and add a LocaleSelector for the menu. Run npx gt translate before next build to write a file for each language. In Osaka, the menu now offers Spanish, French and Japanese, and the reader picks Japanese.',
  'kb-translate-react-app': 'Install gt-react and the gt CLI, list your languages in gt.config.json with the output inside src, add a loadTranslations file, initialize gt-react with initializeGTSPA in a small entry file before your app renders, wrap your text in the T component, and run npx gt translate to write a translation file for each language. In Paris, your React app renders English for a browser that asks for French. Its only text is English, and the app loads no other language. General Translation lets you initialize gt-react before the app renders and wrap its text in T. List your languages in gt.config.json, and add a loadTranslations file. An entry file calls initializeGTSPA first, then loads the rest of the app. Wrap the page\'s text in T, so the CLI finds it. Sign in, set your project ID, and run npx gt translate. Spanish, Japanese or French loads before the app renders, and in Paris it opens in French.',
  'kb-translate-vue-app': 'Install gt-vue, register its plugin with createGT before you mount the app, wrap your template in the T component, and run npx gt translate to write a catalog for each language. In Bogotá, a reader of Spanish finds your Vue page all in English. The template is plain English, and no plugin runs before the app mounts. General Translation lets you register the gt-vue plugin and wrap your template in T. Install gt-vue, a 0.x release whose API may still change. List your languages, register the plugin before the app mounts, and wrap the template in T. Sign in, set your project ID, and run npx gt translate. Add a switcher built on useSetLocale, which loads a language without a reload. In Bogotá, the page switches in place to Japanese, French and Spanish.',
  'kb-translate-react-native-app': 'Install gt-react-native, add its Babel plugin for the Intl polyfills, call initializeGT and wrap your app in GTProvider, mark text with the T component, and run npx gt translate to write a translation file for each language. The package is experimental, and Expo Go is not supported, so Expo apps need a development build. In Lyon, your app opens in English on a phone set to French. Its welcome is a plain Text element that nothing translates. General Translation lets you translate a React Native app with gt-react-native and T. Add its Babel plugin, which supplies the polyfills React Native needs. Call initializeGT with loadTranslations, then wrap the app in GTProvider, which reads the device language. Mark the welcome with T, then sign in and run npx gt translate. The package is experimental, and Expo apps need a development build. Phones set to Spanish or Japanese show them, and in Lyon the app opens in French.',
  'kb-translate-tanstack-start-app': 'Install the experimental gt-tanstack-start package with gt-react and the gt CLI, list your languages in gt.config.json, call initializeGT in the router with them and a loadTranslations file, register gtMiddleware in src/start.ts so each request resolves its locale, pass the locale and its translations from the root route\'s loader to GTProvider, wrap your content in the T component, and run npx gt translate. In Kyoto, a Japanese browser gets your TanStack Start page in English. The server renders this English JSX for every request, and nothing reads its language. General Translation lets you translate a TanStack Start app with gt-tanstack-start. Install the experimental gt-tanstack-start package, and call initializeGT with your languages and a loader. Register gtMiddleware to read each request\'s language, and pass it from the root route to GTProvider. Wrap the page in T, sign in, and run npx gt translate. Now a Spanish browser gets the page in Spanish, and the one in Kyoto gets Japanese.',
  'kb-translate-node-app': 'Install gt-node, call initializeGT once at startup with your locales and a translation loader, wrap each request in withGT, and translate strings in your handlers with getGT. Then list your server files in gt.config.json and run npx gt translate to write a translation file for each language. In Seville, a Spanish browser gets an English greeting from your server. The handler returns a fixed English string for every request. General Translation lets you translate strings into each request\'s locale with gt-node. Call initializeGT once, with your languages and a loader for the translation files. Wrap each request in withGT, using the language from its Accept-Language header. In a handler, await getGT, and pass each string to gt. List server.js in gt.config.json, sign in, and run npx gt translate. Now Japanese, French and Spanish browsers each get their own greeting.',
  'kb-translate-conditional-jsx': 'Instead of translating each side of a ternary separately, wrap the whole sentence in a <T> component and express the condition with <Branch>, so the translator sees the full context and can reorder the sentence for each language. In Shanghai, a reader of Chinese opens your page, and the lunch sentence is in English. Home or work comes from a ternary of English words, and nothing in the app translates the sentence. General Translation lets you wrap whole sentences in T and express conditions with Branch. Run npx gt init, choose Japanese and Chinese, and sign in. Put the sentence in a T component with a Branch, so the translator sees it whole. Run npx gt translate to write Japanese and Chinese with the place before the verb. In Shanghai, the page now shows the Chinese sentence for home and for work.',
  'kb-translate-strings-outside-jsx': 'Use the useGT hook for strings such as placeholders and aria labels, getGT in async App Router components, and msg with useMessages for strings defined at module scope, outside a component. In Vienna, your product list shows its search placeholder and badges in English. The placeholder is an attribute, and the badges come from a constant. General Translation translates placeholders with useGT and constants with msg and useMessages. Call useGT, and pass the placeholder to the function it returns. In async components, await getGT, because they cannot use hooks. For constants, msg registers each string, and useMessages resolves it where you render it. Run npx gt translate to write the Spanish, Japanese and German strings. In Vienna, the placeholder and the badges now read in German.',
  'kb-how-to-handle-plurals-in-react': 'Don\'t hard-code plural logic with checks like n === 1. A small helper is enough for English-only apps, but multilingual apps need locale-aware plural rules, which an i18n component such as <Plural> from gt-react or gt-next handles for every language. In Cairo, a browser asks for Arabic, and your page still shows its count in English. Its plural comes from a check for n equals one, and Arabic needs different sentences for two, three and eleven. General Translation handles plurals in React with the Plural component. Run npx gt init, sign in, then give Plural the count and sentences for zero, for one and for more. Wrap it in a T component, with the count inside Num. Run npx gt translate, and it writes the sentences that Spanish, Japanese and Arabic need. In Cairo, Plural now picks the Arabic sentence for two, for three and for eleven.',
  'kb-format-numbers-dates-currencies': 'Wrap each value in the component for its type: Num for numbers, Currency for money, DateTime for dates and RelativeTime for relative time. Each formats the value for the active locale with JavaScript\'s Intl API, locally, without sending it to a translation service. In Munich, your page writes its total with a decimal point and no euro sign. The code prints each value as it is, unformatted for any locale. General Translation formats values for each locale with Num, Currency and DateTime. After npx gt init, Num groups the count\'s digits, and Currency formats the total without converting it. The DateTime component formats dates, and the RelativeTime component writes phrases such as three days ago. Run npx gt translate, and the words are translated into Spanish, Japanese and German. In Munich, the total and the count now follow German conventions.',
  'kb-multilingual-nextjs-seo': 'Give every language its own URL, set the html lang attribute, point each page\'s canonical URL at itself, add hreflang alternates for every language, translate titles and descriptions, and list every language version in your sitemap. In Madrid, the search result for your About page shows the English title and URL. Your app shows Spanish with gt-next, but that version has no URL or title of its own. General Translation lets you give every language its own URL and tell search engines about them. Move your pages into app/[locale], and the middleware serves Spanish at /es/about. The root layout sets the html lang attribute with useLocale. A helper adds canonical and hreflang links, and getGT translates the title. A sitemap lists every page in every language. In Madrid, the result can now show the Spanish title and URL.',
  'kb-ai-agent-i18n-setup': 'Yes. Copy the start prompt with the Setup for Agents button on generaltranslation.com and paste it into your coding agent. The prompt has the agent read the docs, sign in with gt login, set up the project with flags, translate a first page, and verify the result. In Sapporo, a Japanese reader finds your app is still in English. Your agent ran gt init without flags, and it waits for an answer. General Translation lets your agent set up i18n with the prompt from Setup for Agents. The prompt has your agent run gt login, which you approve. It runs gt init with a flag for every question, so the command asks nothing. Then it wraps your page in the T component, adds a LocaleSelector, and runs gt translate. It builds the app and reports what it actually verified. Your app opens in Spanish and French, and in Japanese for the reader in Sapporo.',
  'kb-review-translations': 'Open the Translations page in the General Translation Dashboard, choose Files or Components and the locales to compare, and click a translation to edit it. Edits are drafts until you click Save. Annotations track the review, and Locadex can open a pull request that brings the edits into your repository. In Lima, your reviewer wants a word removed from the Spanish start button. The label lives in es.json in your repository, and your reviewer does not edit code. General Translation lets you edit any translation on the Translations page in the Dashboard. Compare French and Japanese with the Spanish side by side. Click the Spanish cell, remove the word, and click Save. Add labels and comments so your team can track the review. To bring Dashboard edits into your repository, run a Locadex automation, which opens a pull request. After the merge, the Spanish button in Lima is one word shorter.',
  'kb-translations-in-ci': 'Run npx gt translate in CI before your production build, with a scoped GT_API_KEY and GT_PROJECT_ID from your CI provider\'s secrets. Each build translates new and changed text and ships current translation files. In Montreal, your French page shows the line you added this week in English. Your build script runs next build alone, so the line was never translated. General Translation keeps translations current when your CI runs npx gt translate before the build. Create an API key for CI with the file, context and translation queue permissions. Store it and your project ID as secrets in your CI provider. Add npx gt translate to your build script, before the build command. Run that build on every push to main, for example with a GitHub Actions workflow. Each build then ships current translations in Spanish, Japanese and French.',
  'kb-translate-mintlify-docs': 'Connect the GitHub repository that holds your Mintlify docs to General Translation, choose your languages, and Locadex opens a pull request that restructures docs.json for multiple languages and adds the translated pages. In Hamburg, your Mintlify docs open in English, and the site offers no German. The navigation in docs.json lists one set of English pages and no languages. General Translation lets you choose languages, and Locadex opens a translation pull request. Authorize the General Translation app on GitHub, and choose your docs repository in the Dashboard. Create an automation from the Generate translations and push template for Mintlify, then run its setup with your languages. Locadex\'s pull request adds a navigation entry per language and the translated pages. The merged site\'s menu switches the docs to Spanish, Japanese and German.',
  'kb-translate-sanity-content': 'Install the gt-sanity plugin, add gtPlugin to sanity.config.ts with your locales and document types, and click Translate on a document. Each translation is imported as a draft document with a language field that you can publish and query. In Buenos Aires, your site shows its spring product update only in English. Sanity stores the article as one English document with no language field. General Translation lets you click Translate on a Sanity document with the gt-sanity plugin. Add gtPlugin to sanity.config.ts with your locales and document types. Give the article a language field, and store your API key in a private document. Click Translate on the article, and the plugin imports each translation as a draft. Publish the drafts, then query each language by its language field. Chinese, Japanese and Spanish readers now each get their own article.',
  'kb-translate-storyblok-content': 'Add your languages in Storyblok, connect the space in the General Translation Dashboard with a personal access token, select stories and locales, and click Sync and apply. Translations are written back into each story as draft field-level values that you review and publish in Storyblok. In Marseille, a French reader sees an English headline on your site. The story holds one English headline, and the space has no other language. General Translation lets you connect your space and translate stories with Sync and apply. In Storyblok, add your target languages to the space. In the Dashboard, connect the space with its ID, its region and a personal access token. Choose stories and target locales, check Auto-enable supported fields, and click Sync and apply. Review the Spanish, Japanese and French drafts, publish them, and fetch each language with the language parameter. In Marseille, the published home page now shows its headline in French.',
  'kb-translate-google-slides': 'Open General Translation\'s Locadex add-on, choose your languages, and click Sync and apply. Locadex translates the text, formats each slide so the new text fits, and makes a copy for each language next to the original in Drive. In Berlin, Acme\'s team needs the launch deck in German, and every slide is in English. Drive holds only the English deck, and translated text rarely takes the same space as the English. General Translation lets you choose languages in the Locadex add-on and click Sync and apply. With Google Drive connected to General Translation, open Extensions, then Locadex. Under Translate into, choose German and the other languages, then click Sync and apply. Locadex translates the text, then formats each slide so the new text fits. The slides keep their layout in the Japanese, Chinese and German copies. Each copy sits next to the original in Drive.',
  'kb-translate-srt-subtitles': 'The CLI translates cue text in SubRip (.srt) subtitle files while preserving cue numbers, timestamps, separators, and markup. In Santiago, a viewer turns on the subtitles of your product video, and every line is English. The video has one subtitle file, and every cue in it is English. General Translation translates the text in SRT subtitle files and keeps every timestamp. Install gt, then list the subtitle files in gt.config.json, with one folder per locale. Sign in, add your project ID, and run npx gt translate for the Spanish and French files. Each new file keeps the timing lines and cue numbers, and only the words change. In Santiago, the player loads the new files, and the same cue reads in French or Spanish.',
  'kb-translate-product-walkthroughs': 'Install gt-rrweb, record a product walkthrough once, and replay it in every locale from your published translations. In Frankfurt, a reader of German plays your product walkthrough, and every word is English. It was recorded once in English, and a recording replays the text it captured. General Translation lets you replay a walkthrough with gt-rrweb in every language. Install gt-rrweb, and turn on _tagIds so each T component carries its hash. Mount GTRecorder with your app\'s catalog loader, and record in English with German and Japanese listed. Render GTReplayer with the saved bundle, which carries the German and Japanese text. In Frankfurt, the same walkthrough switches in place to Japanese, then German, with the same clicks.',
  'kb-translate-lottie-animations': 'Translate dotLottie animation files with the General Translation CLI. In Lille, a reader of French opens your onboarding page, and the animation\'s words are English. The words are text inside its .lottie file, and only an English file exists. General Translation translates Lottie animations with npx gt stage and npx gt download. List the animations and the fonts they use in gt.config.json. After you sign in and set your project ID, run npx gt stage, which uploads the fonts first. Run npx gt download until the Spanish and French files are saved, and review them before you publish. In Lille, the same animation plays in Spanish and in French, at its English font size.',
};

/** The films with a research package, each a page at /motion/<slug>. */
export const MOTION_PACKAGE_SLUGS: readonly string[] = [
  'jihe-yuanben',
  'journey-to-the-west',
  'modern-hebrew',
  'nishi-amane',
  'tyndale',
  'hunayn',
];

const FILM_BY_SLUG: ReadonlyMap<string, MotionFilm> = new Map(MOTION_FILMS.map((film) => [film.slug, film]));

/** The film a slug names, or undefined for a slug that is not on the roster. */
export function getMotionFilm(slug: string): MotionFilm | undefined {
  return FILM_BY_SLUG.get(slug);
}

/** Where a film opens: its package page, or its row on /motion. */
export function motionHref(film: MotionFilm): string {
  return film.pkg ? `/motion/${film.slug}` : `/motion#${film.id}`;
}

export const MOTION_STATUS_LABEL: Readonly<Record<MotionStatus, string>> = {
  rendered: 'Rendered',
  'in-production': 'In production',
  planned: 'Planned',
};
